CREATE TABLE "public"."todos" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."todos_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "project" text,
  "who" text,
  "note" text,
  "date" date,
  "status" text DEFAULT 'pending'::text,
  "source" text,
  "sourceDate" date,
  "created_at" timestamp with time zone DEFAULT now(),
  "deleted_at" timestamp with time zone,
  "deleted_by" uuid,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "is_important" boolean DEFAULT false NOT NULL,
  "remind_on" date,
  "category" text DEFAULT 'note'::text,
  "priority" text DEFAULT 'normal'::text,
  "manager_status" text DEFAULT 'none'::text,
  "manager_note" text,
  "note_bn" text,
  "solved_at" timestamp with time zone,
  "extra_notes" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "reminder_enabled" boolean DEFAULT false NOT NULL,
  "reminder_type" text,
  "reminder_interval" integer,
  "reminder_dates" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "next_reminder_at" timestamp with time zone,
  "owner_user_id" uuid DEFAULT auth.uid(),
  "assigned_to_user_id" uuid DEFAULT auth.uid()
) USING "heap";
ALTER TABLE "public"."todos" OWNER TO "postgres";
COMMENT ON COLUMN "public"."todos"."owner_user_id" IS 'Authenticated user who owns or created the To-Do record.';
COMMENT ON COLUMN "public"."todos"."assigned_to_user_id" IS 'Authenticated user responsible for acting on the To-Do and receiving reminders.';
